<section class="user-area"><div class="container user-layout"><?php require view_path('components/user/sidebar.php'); ?><div class="user-main"><header class="user-page-head"><div><span class="eyebrow">Learning</span><h1>دوره‌های من</h1><p>دوره‌های فعال و سابقه یادگیری شما در Mentoris.</p></div><a class="btn btn--primary btn--sm" href="/courses">پیداکردن دوره</a></header><?php if(!empty($courseRequests)): ?><section class="user-course-requests"><h2>درخواست‌های کارگاه شما</h2><?php foreach($courseRequests as $requestItem): $requestedCourse=\App\Services\PublicContentService::course($requestItem['course_slug']); ?><article class="surface"><h3><?= e($requestedCourse['title'] ?? $requestItem['course_slug']) ?></h3><p><?= e(['requested'=>'منتظر بررسی تیم منتوریس','approved'=>'درخواست شما تأیید شده؛ تکمیل ثبت‌نام با هماهنگی تیم انجام می‌شود.','rejected'=>'درخواست تأیید نشده است.','canceled'=>'درخواست لغو شده است.'][$requestItem['status']] ?? $requestItem['status']) ?></p><small>شیوه پرداخت ترجیحی: <?= $requestItem['payment_plan']==='installments' ? 'اقساطی' : 'نقدی' ?></small><a class="btn btn--ghost btn--sm" href="/courses/<?= e($requestItem['course_slug']) ?>">جزئیات کارگاه</a></article><?php endforeach; ?></section><?php endif; ?><?php if ($courses): ?><div class="grid grid--2 user-course-grid"><?php foreach ($courses as $course): require view_path('components/cards/course-card.php'); endforeach; ?></div><?php else: ?><div class="user-empty"><span><?= icon('book', 'ui-icon--lg') ?></span><h2>هنوز دوره‌ای ندارید</h2><p>بعد از نهایی‌شدن ثبت‌نام، دوره‌های شما در این بخش نمایش داده می‌شوند.</p><div class="cluster"><a class="btn btn--primary" href="/courses">مشاهده دوره‌ها</a><a class="btn btn--ghost" href="/programs">مشاهده Programها</a></div></div><?php endif; ?></div></div></section>
